export default async function validate({ downloaded }, context) {
  const bytes = await context.artifact.open(downloaded);
  if (bytes.length < 8 || String.fromCharCode(...bytes.subarray(0, 5)) !== "%PDF-") {
    throw new Error("Downloaded file is not a PDF");
  }
  if (downloaded.mediaType === "application/pdf" && downloaded.name === "output.pdf")
    return { pdf: downloaded };
  return {
    pdf: await context.artifact.put(bytes, { name: "output.pdf", mediaType: "application/pdf" }),
  };
}
